def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    cc = dd = cd = dc = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
        elif a == 'C' and b == 'D':
            cd += 1
        else:
            dc += 1

    opp_def = dd + cd
    my_def = dc + dd

    if n >= 97:
        return 'D'

    if opp_def == 0 and n >= 40 and my_def < n // 10 and n % 5 == 0:
        return 'D'

    if n >= 5 and opp_def >= n - 2:
        return 'D'

    if n >= 5 and (cc + cd) >= n - 2 and dc <= 1:
        return 'C'

    if opp_last == 'C':
        return 'C'

    total = n
    coop_rate = (cc + dc) / total if total else 0

    if coop_rate > 0.6:
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    elif coop_rate > 0.3:
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'
    else:
        if rng.random() < 0.85:
            return 'D'
        return 'C'
